"""Writing generated packages to disk.

Kept apart from the generators so that generation itself stays a pure function
of the configuration and can be tested without touching the filesystem.
"""

from __future__ import annotations

import json
from collections.abc import Iterable, Sequence
from dataclasses import dataclass, field
from pathlib import Path

from .generator import GeneratedFile

#: First bytes of every generated file. Used to tell files this project owns
#: from anything a user has placed in the output directory by hand.
GENERATED_MARKER = "# Generated by hass-energy."

#: Record of the entity ids the last run produced. Hidden, and not YAML, so
#: Home Assistant's package include ignores it.
MANIFEST_NAME = ".hass-energy-manifest.json"


@dataclass(frozen=True)
class WriteResult:
    """What one write or check pass found."""

    written: tuple[Path, ...] = ()
    unchanged: tuple[Path, ...] = ()
    removed: tuple[Path, ...] = ()
    entities_added: tuple[str, ...] = field(default=())
    entities_removed: tuple[str, ...] = field(default=())

    @property
    def changed(self) -> bool:
        """Whether the output directory differed from the generated packages."""

        return bool(self.written or self.removed)


def _obsolete(files: Sequence[GeneratedFile], output_dir: Path) -> list[Path]:
    """Generated files still on disk that the configuration no longer produces."""

    expected = {file.filename for file in files}
    obsolete = []
    for path in sorted(output_dir.glob("*.yaml")):
        if path.name in expected:
            continue
        if path.read_text(encoding="utf-8").startswith(GENERATED_MARKER):
            obsolete.append(path)
    return obsolete


def read_manifest(output_dir: Path) -> tuple[str, ...]:
    """Entity ids recorded by the previous run, empty if there was none."""

    path = output_dir / MANIFEST_NAME
    if not path.exists():
        return ()
    try:
        recorded = json.loads(path.read_text(encoding="utf-8"))["entities"]
    except (ValueError, KeyError, TypeError):
        # A manifest we cannot read is treated as absent: it only exists to
        # report renames, and must never block a regeneration.
        return ()
    return tuple(recorded)


def _entity_changes(
    entities: Sequence[str], output_dir: Path
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    """Entity ids this run adds and drops relative to the recorded manifest."""

    previous = read_manifest(output_dir)
    if not previous:
        return (), ()
    current = set(entities)
    return (
        tuple(entity for entity in entities if entity not in set(previous)),
        tuple(entity for entity in previous if entity not in current),
    )


def write_files(
    files: Iterable[GeneratedFile], output_dir: Path, entities: Sequence[str] = ()
) -> WriteResult:
    """Write packages, leaving unchanged files untouched.

    Files whose content already matches are not rewritten, so their timestamps
    keep reflecting the last real change. Previously generated files the
    configuration no longer produces are removed.
    """

    files = list(files)
    output_dir.mkdir(parents=True, exist_ok=True)
    added, dropped = _entity_changes(entities, output_dir)

    written: list[Path] = []
    unchanged: list[Path] = []
    for file in files:
        path = output_dir / file.filename
        if path.exists() and path.read_text(encoding="utf-8") == file.content:
            unchanged.append(path)
            continue
        path.write_text(file.content, encoding="utf-8")
        written.append(path)

    removed = _obsolete(files, output_dir)
    for path in removed:
        path.unlink()

    manifest = {"entities": list(entities)}
    (output_dir / MANIFEST_NAME).write_text(
        json.dumps(manifest, indent=2, sort_keys=False) + "\n", encoding="utf-8"
    )

    return WriteResult(tuple(written), tuple(unchanged), tuple(removed), added, dropped)


def check_files(
    files: Iterable[GeneratedFile], output_dir: Path, entities: Sequence[str] = ()
) -> WriteResult:
    """Report what writing would change, without changing anything."""

    files = list(files)
    if not output_dir.exists():
        return WriteResult(written=tuple(output_dir / file.filename for file in files))

    added, dropped = _entity_changes(entities, output_dir)

    stale: list[Path] = []
    unchanged: list[Path] = []
    for file in files:
        path = output_dir / file.filename
        if path.exists() and path.read_text(encoding="utf-8") == file.content:
            unchanged.append(path)
        else:
            stale.append(path)

    return WriteResult(
        tuple(stale), tuple(unchanged), tuple(_obsolete(files, output_dir)), added, dropped
    )
